#[inline]
pub async fn _is_led_on_timer() -> bool{
    embassy_futures::yield_now().await;
    IS_LED_ON_TIMER.load(Ordering::Relaxed)
}



use embassy_futures::select::{select, Either};
use embassy_sync::{blocking_mutex::raw::CriticalSectionRawMutex, signal::Signal};

pub static RADAR_DETECTION_TRIGGER: Signal<CriticalSectionRawMutex, ()> = Signal::new();
pub static LED_STATE: Signal<CriticalSectionRawMutex, bool> = Signal::new();

#[embassy_executor::task]
async fn led_on_timer() {
    loop {

        RADAR_DETECTION_TRIGGER.wait().await;
        IS_LED_ON_TIMER.store(true, Ordering::Relaxed);
        LED_STATE.signal(true);


        loop {
            match select(
                delay_micros(SETTINGS.get_on_time_micros()),
                RADAR_DETECTION_TRIGGER.wait(),
            )
            .await
            {
                Either::First(_) => break, // time up
                Either::Second(_) => continue, // new trigger reset delay
            }
        }

        IS_LED_ON_TIMER.store(false, Ordering::Relaxed);
        LED_STATE.signal(false);
    }
}



#[embassy_executor::task]
async fn power_led_fade(){

    loop{
        if _is_led_on_timer().await{

            _pwm_increment().await;

        }else{
            _pwm_decrement().await;
        }
    }
}

#[inline]
async fn _pwm_increment(){

    if LED_PWM_DUTY.load(Ordering::Relaxed) < SETTINGS.working.duty {
        LED_PWM_DUTY.store(LED_PWM_DUTY.load(Ordering::Relaxed) + 1, Ordering::Relaxed);
        delay_micros(SETTINGS.get_fade_in_increment_time()).await;
    }else{
        // embassy_futures::yield_now().await;
        LED_STATE.wait().await;
    }
}

#[inline]
async fn _pwm_decrement(){

    if LED_PWM_DUTY.load(Ordering::Relaxed) > 0 {
        LED_PWM_DUTY.store(LED_PWM_DUTY.load(Ordering::Relaxed) - 1, Ordering::Relaxed);

        delay_micros(SETTINGS.get_fade_out_increment_time()).await;

    }else{
        // embassy_futures::yield_now().await;
        LED_STATE.wait().await;
    }
}

#[inline]
pub fn _get_pwm_duty() -> u32{
    LED_PWM_DUTY.load(Ordering::Relaxed)
}


#[inline]
pub async fn delay_micros (us: u32) {
    embassy_time::Timer::after(embassy_time::Duration::from_micros(us as u64)).await;
}

